import {
    PlaneGeometry,
    Mesh,
    Object3D,
    DoubleSide,
    Texture
} from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    texture as textureNode
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 *
 * @typedef {Object} NodeContext
 * @property {{ textureLoader: { load: (url:string)=>Texture }}} ctx
 * @property {{ [key:string]: Function }} primitives
 * @property {{ fontAtlas: any }} fontAtlas
 */

/**
 * Creates a billboarded sprite node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // --------------------------------------------------------------------
    // Asset loading
    // --------------------------------------------------------------------
    const imageUrl = config.assets?.imageUrl ?? '';
    const mapTexture = ctx.textureLoader.load(imageUrl);

    // --------------------------------------------------------------------
    // Geometry – use aspect ratio of the atlas region (512 / 320 = 1.6)
    // --------------------------------------------------------------------
    const REGION_WIDTH = 512;
    const REGION_HEIGHT = 320;
    const aspect = REGION_WIDTH / REGION_HEIGHT;
    const geometry = new PlaneGeometry(aspect, 1);

    // --------------------------------------------------------------------
    // Material – MeshBasicNodeMaterial with a texture node
    // --------------------------------------------------------------------
    const material = new MeshBasicNodeMaterial();
    material.mapNode = textureNode(mapTexture);
    material.side = DoubleSide;

    // --------------------------------------------------------------------
    // Mesh – placed according to config, billboarded each frame
    // --------------------------------------------------------------------
    const mesh = new Mesh(geometry, material);
    const pos = config.position ?? [0, 0, 0];
    const rot = config.rotation ?? [0, 0, 0];
    const scl = config.scale ?? [1, 1, 1];

    mesh.position.set(pos[0], pos[1], pos[2]);
    mesh.rotation.set(rot[0], rot[1], rot[2]);
    mesh.scale.set(scl[0], scl[1], scl[2]);

    // Billboard – align quaternion with the active camera each render
    mesh.onBeforeRender = (renderer, scene, camera) => {
        mesh.quaternion.copy(camera.quaternion);
    };

    // --------------------------------------------------------------------
    // User data – handlers placeholder & cleanup routine
    // --------------------------------------------------------------------
    mesh.userData.handlers = {};

    mesh.userData.cleanup = () => {
        geometry.dispose();
        material.dispose();
        if (mapTexture && mapTexture instanceof Texture) {
            mapTexture.dispose();
        }
        // Kill any GSAP timelines that might have been added in the future
        gsap.globalTimeline.clear();
    };

    return mesh;
}
